use std::fs

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn digits(s: string) -> int {
    let mut v = 0
    for c in s.chars() {
        if c < '0' || c > '9' {
            return -1
        }
        v = v * 10 + (c as int - '0' as int)
    }
    v
}

// returns days since 1900-01-01, or -1 when invalid
fn parse_date(s: string) -> int {
    let parts: Vec<string> = s.split("-").collect()
    if parts.len() != 3 {
        return -1
    }
    if parts[0].len() != 4 || parts[1].len() != 2 || parts[2].len() != 2 {
        return -1
    }
    let y = digits(parts[0])
    let m = digits(parts[1])
    let d = digits(parts[2])
    if y < 1900 || y > 2100 || m < 1 || m > 12 || d < 1 {
        return -1
    }
    if d > days_in_month(y, m) {
        return -1
    }
    let mut total = 0
    let mut yy = 1900
    while yy < y {
        total += if is_leap(yy) { 366 } else { 365 }
        yy += 1
    }
    let mut mm = 1
    while mm < m {
        total += days_in_month(y, mm)
        mm += 1
    }
    total + d - 1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
    for line in text.lines() {
        let toks: Vec<string> = line.split_whitespace().collect()
        if toks.len() == 0 {
            continue
        }
        if toks.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(toks[0])
        let b = parse_date(toks[1])
        if a < 0 || b < 0 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        // 1900-01-01 was a Monday
        let wd = (lo % 7) as usize
        println("${diff} ${names[wd]}")
    }
}

